/**
 * @summary Get a session by id (host-authenticated)
 */
export const getGetSessionUrl = (id: string, params: GetSessionParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/sessions/${id}?${stringifiedParams}`
    : `/api/sessions/${id}`;
};

export const getSession = async (
  id: string,
  params: GetSessionParams,
  options?: RequestInit,
): Promise<Session> => {
  return customFetch<Session>(getGetSessionUrl(id, params), {
    ...options,
    method: "GET",
  });
};

export const getGetSessionQueryKey = (
  id: string,
  params?: GetSessionParams,
) => {
  return [`/api/sessions/${id}`, ...(params ? [params] : [])] as const;
};

export const getGetSessionQueryOptions = <
  TData = Awaited<ReturnType<typeof getSession>>,
  TError = ErrorType<ErrorResponse>,
>(
  id: string,
  params: GetSessionParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSession>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetSessionQueryKey(id, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getSession>>> = ({
    signal,
  }) => getSession(id, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getSession>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetSessionQueryResult = NonNullable<
  Awaited<ReturnType<typeof getSession>>
>;
export type GetSessionQueryError = ErrorType<ErrorResponse>;

